def code_of(r):
    return r["invite"].rsplit("/", 1)[-1]

def main():
    seen_local = set()
    out = []
    dup_in = 0
    for r in RECORDS:
        c = code_of(r)
        if c in seen_local:
            dup_in += 1
            continue
        seen_local.add(c)
        out.append(r)
    try:
        seen_global = pickle.load(open(SEEN, "rb"))
    except Exception:
        seen_global = set()
    overlap = [r for r in out if code_of(r) in seen_global]
    fresh = [r for r in out if code_of(r) not in seen_global]
    with open(OUT, "w") as f:
        json.dump(fresh, f, indent=1, ensure_ascii=False)
    print(f"total_collected={len(RECORDS)} in_file_dups={dup_in} overlap_with_global={len(overlap)} fresh_saved={len(fresh)}")

if __name__ == "__main__":
    main()
